  questionSchema {
    prompt {
      ...SubmissionCmlContent
      ...SubmissionHtmlContent
    }
    widgetSessionId
  }
  widgetResponse: response {
    answer
  }
}

fragment AutoGradedFeedback on Submission_AutoGradedFeedback {
