AssignmentGradingStatus:
query AssignmentGradingStatus($courseId: ID!, $itemId: ID!) {
  SubmissionState {
    queryState(courseId: $courseId, itemId: $itemId) {
      ... on Submission_QueryStateFailure {
        errors {
          message
        }
      }
      ... on Submission_SubmissionState {
        gradingStatus
        skillsVerifiedAt
        outcome {
          earnedGrade
        }
      }
    }
  }
}
